      `CLAIM_SHARED sheet=${sheet} by=uma person=Ada amount=10.01 date=2026-03-10 with=Cam share=33.33`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=30.01 due-total=2.34 overdue-total=0.00`,
      `ROLLUP sheet=${sheet} by=uma person=Cam claimed=0.00 due-total=0.33 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=30.01 due-total=0.33 overdue-total=0.00`,
